// THE SHARED TRANSACTION SHAPE — what every finance capability folds over.
//
// One definition, because the alternative is each capability inventing its own and the graph carrying
// six subtly different ideas of what a transaction is. The fields are the ones a statement actually
// gives you and nothing more: anything richer (category, merchant identity, account type) is DERIVED
// by a capability that says so, rather than assumed to be present.
import type { Money } from "@/features/finance/lib/money";

export interface Txn {
  /** ISO `YYYY-MM-DD`. Normalised at ingest, because comparing dates written three ways is not
   *  analysis, it is guessing. */
  readonly date: string;
  /** The description exactly as the statement wrote it. Normalisation is a capability's job and is
   *  always reversible to this. */
  readonly description: string;
  /** NEGATIVE is money leaving the account holder — the one contract ingest normalises to. */
  readonly amount: Money;
  /** Which account it belongs to. Two accounts can hold the same charge on the same day. */
  readonly account: string;
}

/** Days between two ISO dates. UTC, so a DST boundary cannot make a 30-day month 29.96 days. */
export function daysBetween(a: string, b: string): number {
  const ms = Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`);
  return Math.round(ms / 86_400_000);
}

/** `YYYY-MM` — the period most statement analysis groups by. */
export const monthOf = (date: string): string => date.slice(0, 7);

/**
 * A merchant key: the description reduced to what is STABLE across occurrences.
 *
 * A recurring charge rarely writes itself identically twice — statements append dates, store numbers,
 * transaction ids and city names. Matching on the raw description would find no recurrence at all,
 * which is the failure mode that makes a subscription detector look like it works while finding
 * nothing.
 *
 * Deliberately crude and DETERMINISTIC: lowercase, drop digits and punctuation, collapse whitespace,
 * take the leading words. A smarter matcher would need a model, and a model here would mean sending
 * someone's merchant list somewhere.
 */
export function merchantKey(description: string, words = 3): string {
  const cleaned = description
    .toLowerCase()
    // SPLIT FIRST, then discard any token that CARRIED a digit.
    //
    // Stripping digits before splitting leaves the LETTER FRAGMENTS of an alphanumeric id behind:
    // `AMZN Mktp US*2X4TY1` reduced to `amzn mktp ty` and `AMZN Mktp US*9KK2P0` to `amzn mktp kk`, so
    // one merchant produced a different key on every occurrence and matched itself never. That is the
    // exact failure that makes a subscription detector look like it works while finding nothing —
    // caught by the `merchantKey` tests, which is what they exist for.
    .split(/[^a-z0-9]+/)
    .filter((w) => w && !/\d/.test(w))
    .filter((w) => w.length > 1)
    .filter((w) => !NOISE.has(w));
  return cleaned.slice(0, words).join(" ");
}

/** Tokens that appear in descriptions without identifying the merchant. */
const NOISE = new Set([
  "purchase", "payment", "pos", "debit", "credit", "card", "recurring", "autopay", "auto",
  "transaction", "ach", "web", "id", "ref", "the", "inc", "llc", "co", "com", "www", "usa", "us",
]);

