import { describe, it, expect } from "vitest";
import { daysBetween, monthOf, merchantKey } from "@/features/finance/lib/txn";

// `merchantKey` IS LOAD-BEARING and was covered only incidentally, through recurring detection and
// duplicates. Both of those would fail in the same confusing way if it broke — as "no subscriptions
// found", which reads like good news — so it gets its own tests rather than being inferred from theirs.

describe("merchantKey — what makes recurrence detectable at all", () => {
  it("survives the noise a statement adds to each occurrence", () => {
    // The same charge, three months running, as three institutions would actually write it. If these
    // do not collapse to one key, a subscription detector finds nothing and looks like it works.
    expect(merchantKey("STREAMSERVICE *RECURRING 12345")).toBe(merchantKey("STREAMSERVICE *RECURRING 99881"));
    expect(merchantKey("SQ *COFFEE BAR 4471")).toBe(merchantKey("SQ *COFFEE BAR 9903"));
    expect(merchantKey("AMZN Mktp US*2X4TY1")).toBe(merchantKey("AMZN Mktp US*9KK2P0"));
  });

  it("drops the words that appear everywhere and identify nobody", () => {
    // `PURCHASE`, `POS`, `RECURRING`, `INC` and friends are on half of all descriptions. Keeping them
    // would make unrelated merchants collide, which is worse than missing a match: it merges two
    // different charges into one confident finding.
    expect(merchantKey("POS PURCHASE ACME HARDWARE INC")).toBe(merchantKey("ACME HARDWARE"));
    expect(merchantKey("RECURRING PAYMENT GYMCO LLC")).toBe(merchantKey("GYMCO"));
  });

  it("does NOT collapse two different merchants together", () => {
    // The collision that would matter: two real merchants reduced to one key means one report line
    // for two unrelated charges.
    expect(merchantKey("NORTH BAKERY")).not.toBe(merchantKey("SOUTH BAKERY"));
    expect(merchantKey("CITY POWER")).not.toBe(merchantKey("CITY WATER"));
  });

  it("is case- and punctuation-insensitive, and stable under whitespace", () => {
    expect(merchantKey("  the   Corner-Store,  Inc.  ")).toBe(merchantKey("THE CORNER STORE INC"));
  });

  it("returns EMPTY for a description with nothing identifying in it", () => {
    // An empty key must not become a group: grouping on "" would pool every anonymous line into one
    // fictitious merchant, and it would look like the biggest subscription in the report.
    expect(merchantKey("1234 5678")).toBe("");
    expect(merchantKey("POS DEBIT CARD")).toBe("");
    expect(merchantKey("")).toBe("");
  });

  it("is deterministic", () => {
    const d = "SQ *SOME MERCHANT 8891";
    expect(merchantKey(d)).toBe(merchantKey(d));
  });
});

describe("daysBetween", () => {
  it("counts whole days, and is signed", () => {
    expect(daysBetween("2026-01-01", "2026-01-31")).toBe(30);
    expect(daysBetween("2026-01-31", "2026-01-01")).toBe(-30);
    expect(daysBetween("2026-03-04", "2026-03-04")).toBe(0);
  });

  it("crosses a month, a year and a leap day without drifting", () => {
    expect(daysBetween("2026-12-31", "2027-01-01")).toBe(1);
    expect(daysBetween("2024-02-28", "2024-03-01")).toBe(2); // 2024 is a leap year
  });

  it("is UTC, so a DST boundary cannot make a month 29.96 days", () => {
    // Parsed as local time, a spring-forward inside the range rounds to 29 and a monthly charge stops
    // being classified as monthly — in exactly one month of the year, which is the worst kind of bug.
    expect(daysBetween("2026-03-01", "2026-03-31")).toBe(30);
    expect(daysBetween("2026-10-25", "2026-11-25")).toBe(31);
  });
});

describe("monthOf", () => {
  it("is the YYYY-MM period", () => {
    expect(monthOf("2026-03-04")).toBe("2026-03");
    expect(monthOf("2026-12-31")).toBe("2026-12");
  });
});
